function [cd] = drag_cd(has_cfg, cfg_cd, has_sc, sc_cd)
%DRAG_CD  The cannonball's drag coefficient forces.drag takes: the force set's when it states one, else the spacecraft's,
%   else 2.2.
%   has_cfg: bool (passed true or false)
%   cfg_cd: real[1] (passed a plain number)
%   has_sc: bool (passed true or false)
%   sc_cd: real[1] (passed a plain number)
%   returns cd: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    cd = 0;
    if has_cfg
        cd = cfg_cd;
    elseif has_sc
        cd = sc_cd;
    else
        cd = 2.2;
    end
end
